import{mountReviewPositionHud}from'./review-position-hud.mjs';
import {installJangmokSelectedServices} from './jangmok/selected-services-host.mjs';
/** Sole main RAF drives this owner. No storage, warp, economics or alternate movement. */
export function installJangmokServiceReviewHost({root,canvas,getWorld,environment,clearInput,loadController,onStatus,onStateChanged=()=>{},healBinding,shopBinding,setAdapter,getAdapter,loadVisuals,windowTarget=root.ownerDocument.defaultView}){
 const doc=root.ownerDocument;let controller=null,services=null,visuals=null,loading=false,disposed=false,acting=false,epoch=0,focused=doc.hasFocus?.()!==false;
 const bar=doc.createElement('section');bar.dataset.nativeReview='';const note=doc.createElement('p');note.textContent='장목 서비스 연결 개발 검토 · 원래 회복/구매 처리 · 집·계단 원본 유지';bar.append(note);
 const current=()=>!disposed&&controller&&getAdapter()===controller&&controller.world===getWorld();
 const positionHud=mountReviewPositionHud({container:bar,enabled:import.meta.env?.DEV===true,read:()=>{const s=current()?controller.snapshot()?.native:null;return{scene:s?.sceneId??s?.scene,foot:s?.foot,facing:s?.facing,pending:loading||acting||!!s?.pending||!!getWorld()?.story.pendingCommit}}});
 const focusBindings=v=>{healBinding.setFocused(v);shopBinding.setFocused(v);};
 const stop=()=>{controller?.stop();if(current())clearInput();};
 const report=e=>{if(!disposed)onStatus(e?.message??String(e));};
 const buttons=[];const button=(label,run,{pending=false}={})=>{const b=doc.createElement('button');b.textContent=label;b.onclick=async()=>{if(disposed||loading||acting||(!pending&&services?.blocksInput))return;const ownerWorld=getWorld();try{await run()}catch(e){if(getWorld()===ownerWorld&&e?.message!=='STALE_JANGMOK_LOAD')report(e)}finally{sync()}};buttons.push(b);bar.append(b);return b;};
 const cleanup=()=>{services?.dispose();services=null;const old=controller;if(getAdapter()===old)focusBindings(false);controller=null;if(getAdapter()===old)setAdapter(null);old?.dispose();visuals?.dispose?.();visuals=null;};
 async function enter(home){const w=getWorld();if(!w||w.inputLocked||w.busy)throw Error('CANONICAL_INPUT_LOCKED');if(controller?.active)throw Error('NATIVE_ALREADY_ACTIVE');const mine=++epoch;loading=true;clearInput();sync();let next=null,art=null;try{cleanup();next=await loadController({world:w,canonicalEnvironment:environment,clearInput:()=>{if(!disposed&&mine===epoch&&getWorld()===w)clearInput();},selectedServices:true});if(disposed||mine!==epoch||getWorld()!==w)throw Error('STALE_JANGMOK_LOAD');art=await loadVisuals();if(disposed||mine!==epoch||getWorld()!==w)throw Error('STALE_JANGMOK_LOAD');next.enter(home);controller=next;visuals=art;next=null;art=null;setAdapter(controller);focusBindings(focused);services=installJangmokSelectedServices({container:root,getWorld,getScene:()=>current()?controller:null,healBinding,shopBinding,visuals,onStateChanged:()=>{if(current()&&focused)onStateChanged()},onMessage:value=>{if(!disposed&&mine===epoch&&getWorld()===w&&current())report(value)},retryCommit:w=>w.story.retryCommit(),windowTarget,clearInput});report('장목 원본 보행 · 위쪽을 보고 멈춘 뒤 Z 조사 · 회복/구매는 명시 선택');}finally{next?.dispose();art?.dispose?.();if(mine===epoch)loading=false;sync();}}
 const upper=button('장목 · 위쪽 집',()=>enter('upper')),family=button('장목 · 가족 집',()=>enter('family')),coastal=button('장목 · 해안 집',()=>enter('coastal'));
 const open=button('DEV 선택 집 문 열기',()=>controller.openDoor());
 const routes=['door','stairs','exit'].map((t,i)=>button(['문 앞','계단','현관'][i],()=>controller.routeTo(t)));
 const retry=button('보류된 원래 처리 재시도',()=>services.retryPending(),{pending:true});
 const back=button('canonical 본편 복귀',()=>{if(!current()||getWorld().inputLocked)return;controller.exit();cleanup();clearInput();canvas.width=960;canvas.height=540;onStateChanged();canvas.focus();});
 function sync(){if(disposed)return;const active=!!controller?.active,locked=loading||acting||!!services?.blocksInput;for(const b of [upper,family,coastal])b.disabled=loading||active;for(const b of [open,...routes,back])b.disabled=!active||locked;retry.disabled=!active||loading||acting||services?.active||!getWorld()?.story.pendingCommit;root.dataset.nativeReviewActive=String(active);root.dataset.nativeReviewLoading=String(loading);positionHud.refresh();}
 const pause=()=>{focused=false;services?.pause();focusBindings(false);stop();controller?.releaseAction();};
 const resume=()=>{if(disposed||doc.hidden||doc.hasFocus?.()===false)return;focused=true;focusBindings(current());services?.resume();controller?.releaseAction();if(current()&&controller.active)onStateChanged();sync();};
 const keyup=e=>{if(['z','Z','Enter',' ','a','A'].includes(e.key)){services?.releaseAction();controller?.releaseAction();}};
 const visibility=()=>doc.hidden?pause():resume();windowTarget.addEventListener('blur',pause);windowTarget.addEventListener('focus',resume);windowTarget.addEventListener('keyup',keyup,true);doc.addEventListener('visibilitychange',visibility);root.querySelector('.world-play').prepend(bar);sync();
 return{bar,get active(){return !!controller?.active},get blocked(){return loading||!!controller?.active},frame(dt,direction){if(!current()){if(controller)cleanup();return;}services.frame(dt);if(focused&&!services.blocksInput&&!getWorld().inputLocked)controller.frame(dt,direction);else controller.stop();controller.draw(canvas.getContext('2d'));sync();},async action(){if(!current()||!focused||acting)return;const result=services.action();if(result!==false){sync();return result;}const own=controller,w=getWorld(),mine=epoch;acting=true;try{return await own.action();}finally{own.releaseAction();if(!disposed&&mine===epoch&&controller===own&&getWorld()===w){acting=false;sync();}}},cancel(){if(services?.active){services.pause();return;}if(current()&&!getWorld().inputLocked)controller.cancel();clearInput();sync();},pause,resume,releaseAction(){services?.releaseAction();controller?.releaseAction();},dispose(){if(disposed)return;disposed=true;epoch++;cleanup();windowTarget.removeEventListener('blur',pause);windowTarget.removeEventListener('focus',resume);windowTarget.removeEventListener('keyup',keyup,true);doc.removeEventListener('visibilitychange',visibility);positionHud.dispose();bar.remove();}};
}
